    printf("n = %d\n",n);
    printf("sum=&d\n",myfun3(90,66));
    return 0;
}

void myfun1(){
    printf("hello world\n");
    return ;
}

//a、b形参，存在实参的值
void myfun2(int a,int b){
    int sum;
    sum = a + b;

    printf("%d + %d = %d\n",a,b,sum);
}
int myfun3(int a,int b){
